import java.util.*;
import java.io.*;

public class VariantThree {
    public static void main(String[] args) throws Exception {
        new VariantThree().solve();
    }

    public void solve() throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        long k = sc.nextLong();
        final long MOD = 998244353;

        if (k >= n) {
            pw.println(0);
            pw.close();
            return;
        }

        long[] factorial = new long[n + 1];
        long[] invFactorial = new long[n + 1];
        factorial[0] = 1;
        invFactorial[0] = 1;

        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % MOD;
            invFactorial[i] = modInverse(factorial[i], MOD);
        }

        int r = (int) (n - k);
        long total = 0;

        for (int i = 1; i <= r; i++) {
            long term = factorial[r] * invFactorial[r - i] % MOD;
            term = term * invFactorial[i] % MOD;
            term = term * power(i, n, MOD) % MOD;
            if ((r - i) % 2 == 1) {
                term = -term;
            }
            total = (total + term + MOD) % MOD;
        }

        long result;
        if (k == 0) {
            result = total * factorial[n] % MOD;
            result = result * invFactorial[r] % MOD;
            result = result * invFactorial[n - r] % MOD;
        } else {
            result = 2 * total % MOD;
            result = result * factorial[n] % MOD;
            result = result * invFactorial[r] % MOD;
            result = result * invFactorial[n - r] % MOD;
        }
        pw.println(result);
        pw.close();
    }

    private long power(long base, int exp, long mod) {
        long res = 1;
        long cur = base % mod;
        for (int i = 0; i < exp; i++) {
            res = (res * cur) % mod;
        }
        return res;
    }

    private long modInverse(long a, long m) {
        return power(a, (int) m - 2, m);
    }
}
